#include <os/list.h>
#include <os/mm.h>
#include <os/sched.h>
#include <pgtable.h>
#include <os/string.h>
#include <os/sched.h>
#include <os/irq.h>
#include <assert.h>

ptr_t kernel_memCurr = KERNEL_MEM_BEGIN;
ptr_t user_memCurr = USER_MEM_BEGIN;

user_page_t user_page[USER_PAGE_NUM];
shm_page_t shm_page[SHM_PAGE_NUM];
disk_page_t disk_page[DISK_PAGE_NUM];
pgdir_page_t pgdir_page[PGDIR_PAGE_NUM];

// returns pa
PTE* alloc_pgdir_page()
{
    int i;
    for(i = 0; i < PGDIR_PAGE_NUM; i++){
        if(pgdir_page[i].valid == 0){
            break;
        }
    }
    assert(i != PGDIR_PAGE_NUM);
    pgdir_page[i].valid = 1;
    PTE *ret = (PTE*)(FREE_PGDIR_ADDR + i * PAGE_SIZE);
    clear_pgdir((PTE*)pa2kva((uintptr_t)ret));
    return ret;
}

void free_pgdir_page(uintptr_t addr)
{
    int i = (addr - FREE_PGDIR_ADDR) / PAGE_SIZE;
    pgdir_page[i].valid = 0;
}

int pa2num(uintptr_t pa)
{
    return (pa - USER_MEM_BEGIN) / PAGE_SIZE;
}
ptr_t num2pa(int num)
{
    return (USER_MEM_BEGIN + num * PAGE_SIZE);
}

// returns pa
ptr_t alloc_user_page(uint8_t pin, PTE* pgtable)
{
    int i;
    for(i = 0; i < USER_PAGE_NUM; i++){
        if(user_page[i].valid == 0){
            break;
        }
    }

    ptr_t pa;
    if(i == USER_PAGE_NUM){
        /* physical memory is exhausted: swap somebody else out first */
        pa = selete_page();
        write_to_sd(pa);
        i = pa2num(pa);
    }
    else{
        pa = num2pa(i);
    }

    user_page[i].valid = 1;
    user_page[i].pin = pin;
    user_page[i].pgtable = pgtable;

    /* a fresh page must not leak the previous owner's data */
    memset((void*)pa2kva(pa), 0, PAGE_SIZE);
    return pa;
}

// baseAddr is pa
void free_user_page(ptr_t baseAddr)
{
    user_page[pa2num(baseAddr)].valid = 0;
}

// returns pa
void *kmalloc(size_t size)
{
    // align 4
    ptr_t ret = ROUND(kernel_memCurr, 4);
    kernel_memCurr = ret + size;
    return (void*)ret;
}

// select a user page to write to disk (NRU), returns pa
ptr_t selete_page()
{
    /* Not Recently Used with a second chance: sweep the frames, give every
     * page whose accessed bit is set one more round (clearing the bit as we
     * pass by), and evict the first one that survived a whole sweep unused.
     * Pinned frames (kernel stacks, shared pages) and frames that are not
     * reachable through a page table entry can never be evicted. */
    static int clock_hand = 0;

    for(int step = 0; step < 2 * USER_PAGE_NUM; step++){
        int i = clock_hand;
        clock_hand = (clock_hand + 1) % USER_PAGE_NUM;

        if(!user_page[i].valid || user_page[i].pin || user_page[i].pgtable == NULL){
            continue;
        }
        if(get_attribute(*user_page[i].pgtable, _PAGE_ACCESSED)){
            clear_attribute(user_page[i].pgtable, _PAGE_ACCESSED);
            continue;
        }
        return num2pa(i);
    }

    /* every single frame is pinned, there is nothing we can do */
    assert(0);
    return 0;
}

void write_to_sd(ptr_t pa)
{
    int i;
    for(i = 0; i < DISK_PAGE_NUM; i++){
        if(disk_page[i].valid == 0){
            break;
        }
    }
    assert(i != DISK_PAGE_NUM);
    disk_page[i].valid = 1;

    sbi_sd_write((unsigned int)pa, PAGE_SD_BLOCKS, SWAP_BEGIN + i * PAGE_SD_BLOCKS);

    /* Remember where the page went inside its own page table entry: the
     * frame number field now holds the swap slot and _PAGE_SOFT marks the
     * entry as "on disk" so that the page fault handler can tell it apart
     * from a never-mapped address. */
    PTE *pgtable = user_page[pa2num(pa)].pgtable;
    if(pgtable != NULL){
        clear_attribute(pgtable, _PAGE_PRESENT);
        set_attribute(pgtable, _PAGE_SOFT);
        set_pfn(pgtable, (uint64_t)i);
    }

    flush_tlb_all();
    free_user_page(pa);
}

unsigned long free_page_num()
{
    unsigned long ret = 0;
    for(int i = 0; i < USER_PAGE_NUM; i++){
        if(user_page[i].valid == 0){
            ret++;
        }
    }
    return ret;
}

/* Walk the three levels of `pgdir` (a pa) down to the leaf entry for `va`,
 * creating the intermediate tables on the way. Returns a pointer to the leaf
 * PTE, which the caller reaches through the kernel's direct mapping. */
static PTE* walk_pgdir(uintptr_t va, uintptr_t pgdir)
{
    uint64_t vpn[3];
    vpn[2] = (va >> VPN2_SHIFT) & VPN_MASK;
    vpn[1] = (va >> VPN1_SHIFT) & VPN_MASK;
    vpn[0] = (va >> VPN0_SHIFT) & VPN_MASK;

    PTE *table = (PTE*)pa2kva(pgdir);
    for(int level = 2; level > 0; level--){
        PTE *entry = table + vpn[level];
        if(!get_attribute(*entry, _PAGE_PRESENT)){
            PTE *next = alloc_pgdir_page();
            *entry = 0;
            set_pfn(entry, (uintptr_t)next >> NORMAL_PAGE_SHIFT);
            /* a pointer entry carries no R/W/X bits */
            set_attribute(entry, _PAGE_PRESENT);
        }
        table = (PTE*)pa2kva(get_pa(*entry));
    }
    return table + vpn[0];
}

/* Same walk, but without creating anything: returns NULL when the address is
 * not backed by a leaf entry at all. */
PTE* find_pte(uintptr_t va, uintptr_t pgdir)
{
    uint64_t vpn[3];
    vpn[2] = (va >> VPN2_SHIFT) & VPN_MASK;
    vpn[1] = (va >> VPN1_SHIFT) & VPN_MASK;
    vpn[0] = (va >> VPN0_SHIFT) & VPN_MASK;

    PTE *table = (PTE*)pa2kva(pgdir);
    for(int level = 2; level > 0; level--){
        PTE *entry = table + vpn[level];
        if(!get_attribute(*entry, _PAGE_PRESENT)){
            return NULL;
        }
        table = (PTE*)pa2kva(get_pa(*entry));
    }
    return table + vpn[0];
}

/*
 * Make sure `va` is backed by a physical frame in `pgdir` (a pa) and return
 * the kernel virtual address of that frame.  A page that had been swapped out
 * is read back from the SD card first.  The signature matches the callback
 * load_elf() expects, so it doubles as the "prepare page" hook of do_exec().
 */
uintptr_t alloc_page_helper(uintptr_t va, uintptr_t pgdir)
{
    va = ROUNDDOWN(va, PAGE_SIZE);
    PTE *pte = walk_pgdir(va, pgdir);

    if(!get_attribute(*pte, _PAGE_PRESENT)){
        if(get_attribute(*pte, _PAGE_SOFT)){
            /* the page lives in the swap area, fetch it back */
            uint64_t slot = get_pfn(*pte);
            uintptr_t pa = alloc_user_page(0, pte);
            sbi_sd_read((unsigned int)pa, PAGE_SD_BLOCKS, SWAP_BEGIN + slot * PAGE_SD_BLOCKS);
            disk_page[slot].valid = 0;
            *pte = 0;
            set_pfn(pte, pa >> NORMAL_PAGE_SHIFT);
        }
        else{
            uintptr_t pa = alloc_user_page(0, pte);
            *pte = 0;
            set_pfn(pte, pa >> NORMAL_PAGE_SHIFT);
        }
        set_attribute(pte, _PAGE_PRESENT | _PAGE_READ | _PAGE_WRITE | _PAGE_EXEC |
                           _PAGE_USER | _PAGE_ACCESSED | _PAGE_DIRTY);
        flush_tlb_all();
    }

    return pa2kva(get_pa(*pte));
}

/*
 * Virtual Memory Layout
 * 0x0_0000_1000 ~ 0x0_0001_0000: share
 * 0x0_0001_0000 ~ 0x0_0001_3000: code
 * 0xf_0000_f000 ~ 0xf_0001_0000: stack
 */
PTE* init_page_table()
{
    PTE *pgdir = alloc_pgdir_page();
    PTE *pgdir_kva = (PTE*)pa2kva((uintptr_t)pgdir);
    PTE *kernel_pgdir_kva = (PTE*)pa2kva(PGDIR_PA);

    /* Every address space keeps the kernel mapped: VPN2 of the kernel window
     * 0xffffffc0_00000000 is 0x101 and boot.c installed it there. */
    pgdir_kva[0x101] = kernel_pgdir_kva[0x101];

    /* init_pcb() resolves addresses with get_kva_of(), which only walks the
     * table, so the whole code region has to be mapped up front. */
    for(uintptr_t va = USER_CODE_BEGIN; va < USER_CODE_END; va += PAGE_SIZE){
        alloc_page_helper(va, (uintptr_t)pgdir);
    }
    /* and one page of user stack to start on */
    alloc_page_helper(USER_STACK_ADDR - PAGE_SIZE, (uintptr_t)pgdir);

    return pgdir;
}

void free_process_user_page(PTE* pgdir)
{
    if(pgdir == NULL || (uintptr_t)pgdir == PGDIR_PA){
        return;
    }

    PTE *pgdir_kva = (PTE*)pa2kva((uintptr_t)pgdir);

    /* Only the user half is owned by this process; VPN2 >= 0x100 belongs to
     * the kernel window, which is shared by everybody. */
    for(int vpn2 = 0; vpn2 < NUM_PTE_ENTRY / 2; vpn2++){
        if(!get_attribute(pgdir_kva[vpn2], _PAGE_PRESENT)){
            continue;
        }
        uintptr_t second_pa = get_pa(pgdir_kva[vpn2]);
        PTE *second_kva = (PTE*)pa2kva(second_pa);

        for(int vpn1 = 0; vpn1 < NUM_PTE_ENTRY; vpn1++){
            if(!get_attribute(second_kva[vpn1], _PAGE_PRESENT)){
                continue;
            }
            uintptr_t third_pa = get_pa(second_kva[vpn1]);
            PTE *third_kva = (PTE*)pa2kva(third_pa);

            for(int vpn0 = 0; vpn0 < NUM_PTE_ENTRY; vpn0++){
                PTE leaf = third_kva[vpn0];
                if(leaf == 0){
                    continue;
                }
                if(get_attribute(leaf, _PAGE_PRESENT)){
                    uintptr_t pa = get_pa(leaf);
                    int shared = 0;
                    /* a shared page only goes away with its last user */
                    for(int k = 0; k < SHM_PAGE_NUM; k++){
                        if(shm_page[k].count > 0 && shm_page[k].pa == pa){
                            shm_page[k].count--;
                            if(shm_page[k].count == 0){
                                free_user_page(pa);
                                shm_page[k].pa = 0;
                            }
                            shared = 1;
                            break;
                        }
                    }
                    if(!shared){
                        free_user_page(pa);
                    }
                }
                else if(get_attribute(leaf, _PAGE_SOFT)){
                    /* the page was swapped out, give the disk slot back */
                    disk_page[get_pfn(leaf)].valid = 0;
                }
                third_kva[vpn0] = 0;
            }

            free_pgdir_page(third_pa);
            second_kva[vpn1] = 0;
        }

        free_pgdir_page(second_pa);
        pgdir_kva[vpn2] = 0;
    }

    free_pgdir_page((uintptr_t)pgdir);
    flush_tlb_all();
}

uintptr_t shm_page_get(int key)
{
    shm_page_t *page = &shm_page[(uint32_t)key % SHM_PAGE_NUM];

    if(page->count == 0){
        /* first user of this key: give the group a pinned frame, it must
         * never be swapped out behind the back of the other sharers */
        page->pa = alloc_user_page(1, NULL);
    }

    uintptr_t pgdir = (uintptr_t)current_running[cpu_id]->pgdir;
    for(uintptr_t va = SHM_VA_BEGIN; va < SHM_VA_END; va += PAGE_SIZE){
        PTE *pte = walk_pgdir(va, pgdir);
        if(get_attribute(*pte, _PAGE_PRESENT) || get_attribute(*pte, _PAGE_SOFT)){
            continue;
        }
        *pte = 0;
        set_pfn(pte, page->pa >> NORMAL_PAGE_SHIFT);
        set_attribute(pte, _PAGE_PRESENT | _PAGE_READ | _PAGE_WRITE |
                           _PAGE_USER | _PAGE_ACCESSED | _PAGE_DIRTY);
        page->count++;
        flush_tlb_all();
        return va;
    }

    /* the share window of this process is full */
    if(page->count == 0){
        free_user_page(page->pa);
        page->pa = 0;
    }
    return 0;
}

void shm_page_dt(uintptr_t addr)
{
    uintptr_t pgdir = (uintptr_t)current_running[cpu_id]->pgdir;
    PTE *pte = find_pte(ROUNDDOWN(addr, PAGE_SIZE), pgdir);

    if(pte == NULL || !get_attribute(*pte, _PAGE_PRESENT)){
        return;
    }

    /* only a page that really belongs to a share group may be detached,
     * otherwise a bogus address would silently unmap private memory */
    uintptr_t pa = get_pa(*pte);
    for(int i = 0; i < SHM_PAGE_NUM; i++){
        if(shm_page[i].count > 0 && shm_page[i].pa == pa){
            *pte = 0;
            flush_tlb_all();

            shm_page[i].count--;
            if(shm_page[i].count == 0){
                free_user_page(pa);
                shm_page[i].pa = 0;
            }
            return;
        }
    }
}

void handle_page_fault(regs_context_t *regs, uint64_t stval, uint64_t cause)
{
    /* Anything outside the user half of the Sv39 address space is a genuine
     * kernel bug; let the generic handler dump the context. */
    if(stval >= (1lu << (VPN2_SHIFT + PPN_BITS - 1))){
        handle_other(regs, stval, cause);
        return;
    }

    /* demand paging: give the faulting address a frame (or fetch it back
     * from the swap area) and let the instruction run again */
    alloc_page_helper(stval, (uintptr_t)current_running[cpu_id]->pgdir);
}

