/* * * * * * * * * * * * * * * * * * * * * * * 
Memory Layout
0x5000_0000 ~ 0x5020_0000       BBL
0x5020_0000 ~ 0x5040_0000       Boot
0x5040_0000 ~ 0x5060_0000       Kernel
0x5060_0000 ~ 0x5060_2000       Kernel Stack
0x5060_2000 ~ 0x5100_0000       Kernel Mem
0x5100_0000 ~ 0x5e00_0000       User Mem
0x5e00_0000 ~ 0x6000_0000       Page Table
* * * * * * * * * * * * * * * * * * * * * * */

#define PAGE_SIZE 4096
#define INIT_KERNEL_STACK   0xffffffc050600000lu    //kva
#define USER_STACK_ADDR     0xf00010000lu           //va

#define KERNEL_MEM_BEGIN    0x50602000lu            //pa
#define KERNEL_MEM_END      0x51000000lu            //pa
#define USER_MEM_BEGIN      0x51000000lu            //pa
#define USER_MEM_END        0x5e000000lu            //pa
#define MEM_END             0x60000000lu            //pa

#define SWAP_BEGIN 2048

/* Rounding: only works for n = power of two */
#define ROUND(a, n)     (((((uint64_t)(a))+(n)-1)) & ~((n)-1))
#define ROUNDDOWN(a, n) (((uint64_t)(a)) & ~((n)-1))

extern ptr_t kernel_memCurr;
extern ptr_t user_memCurr;

#define FREE_PGDIR_ADDR (PGDIR_PA + 2 * PAGE_SIZE)
#define PGDIR_PAGE_NUM ((MEM_END - FREE_PGDIR_ADDR) / PAGE_SIZE)
typedef struct pgdir_page{
    uint8_t valid;
}pgdir_page_t;
extern pgdir_page_t pgdir_page[PGDIR_PAGE_NUM];

#define USER_MEM_SIZE (USER_MEM_END - USER_MEM_BEGIN)
#define USER_PAGE_NUM (USER_MEM_SIZE / PAGE_SIZE)
typedef struct user_page{
    uint8_t valid;
    uint8_t pin;
    PTE* pgtable;
}user_page_t;
extern user_page_t user_page[USER_PAGE_NUM];

#define SHM_PAGE_NUM 100
typedef struct shm_page{
    int count;
    uintptr_t pa;
}shm_page_t;
extern shm_page_t shm_page[SHM_PAGE_NUM];

#define DISK_PAGE_NUM 256
typedef struct disk_page{
    uint8_t valid;
}disk_page_t;
extern disk_page_t disk_page[DISK_PAGE_NUM];

extern PTE* alloc_pgdir_page();
extern void free_pgdir_page(uintptr_t addr);
extern ptr_t alloc_user_page(uint8_t pin, PTE* pgtable);
extern void free_user_page(ptr_t baseAddr);
extern void* kmalloc(size_t size);

extern ptr_t selete_page();
extern void write_to_sd(ptr_t pa);
extern unsigned long free_page_num();

extern PTE* init_page_table();
extern void free_process_user_page(PTE* pgdir);

/* pgdir is pa. if va is not mapped, then map it. returns the kva of the page */
extern uintptr_t alloc_page_helper(uintptr_t va, uintptr_t pgdir);
extern PTE* find_pte(uintptr_t va, uintptr_t pgdir);

/* user virtual address window reserved for shared pages: it stops right
 * below the first page a user ELF is linked at (its headers live at 0xf000) */
#define SHM_VA_BEGIN 0x1000lu
#define SHM_VA_END   0xf000lu

/* the image of a user program, headers included, and the first page of its
 * stack are mapped when the address space is created */
#define USER_CODE_BEGIN 0xf000lu
#define USER_CODE_END   0x14000lu

/* one 4KB page is eight 512 byte SD card blocks */
#define SD_BLOCK_SIZE 512
#define PAGE_SD_BLOCKS (PAGE_SIZE / SD_BLOCK_SIZE)

uintptr_t shm_page_get(int key);
extern void shm_page_dt(uintptr_t addr);

extern void enable_sum();
extern void disable_sum();

#endif /* MM_H */

